// 2026-10-30 LATITUDE の旅人の地図（components/latitude/TravellerMap.tsx）で使う、陸の形と場所の座標。
// 陸の形は Natural Earth 50m（world-atlas@2.0.2 の land-50m）を、北緯73°〜14°・西経28°〜東経150° で切り、
// 北緯46°で縦横をそろえた正距円筒図法で 1000 幅に写し、d3-geo で切って単純化した物（作り直しは vault.vual.jp/tools/latitude-worldmap.mjs）。
// 新しい号を足したら PLACES に、その号の場所（緯度・経度）を1行足す。無い号は地図に出ない。

import { PEOPLE, liveIssues } from '@/lib/latitude';

export const MAP_W = 1000;
export const MAP_H = 477.2;
const LON0 = -28, LAT1 = 73, K = 0.694658, SC = 8.087396;
export const project = (lat: number, lon: number) => ({ x: (lon - LON0) * K * SC, y: (LAT1 - lat) * SC });

// 号の場所（slug → [緯度, 経度]）。その日の中心になった所
export const PLACES: Record<string, [number, number]> = {
  iceland: [64.15, -21.94], // Reykjavík
  copenhagen: [55.68, 12.57],
  london: [51.51, -0.12],
  edinburgh: [55.95, -3.19],
  milan: [45.46, 9.19],
  faro: [57.92, 19.13],
  klippan: [56.13, 13.13],
  vienna: [48.21, 16.37],
  kanazawa: [36.56, 136.66],
};

// 6人の住む街（person slug → [緯度, 経度]）
export const HOMES: Record<string, [number, number]> = {
  solveig: [60.39, 5.32], // Bergen
  klara: [50.08, 14.44], // Prague
  maeve: [51.53, -0.06], // east London
  liv: [57.71, 11.97], // Gothenburg
  helene: [45.76, 4.84], // Lyon
  rin: [35.68, 139.69], // Tokyo
};

// 地図に渡す6人の旅（住む街 → 公開ずみの1日を号の順に）。PLACES に無い号は飛ばす
export function mapTravellers(now: number = Date.now()) {
  const days = liveIssues(now).filter((i) => i.person && PLACES[i.slug]).sort((a, b) => a.no - b.no);
  return PEOPLE.map((p) => {
    const [hl, hn] = HOMES[p.slug] ?? [0, 0];
    return {
      slug: p.slug,
      name: p.name,
      home: { ...project(hl, hn), city: p.home.split(',')[0].replace(/ \(.*\)/, '') },
      stops: days.filter((i) => i.person === p.slug).map((i) => {
        const [la, lo] = PLACES[i.slug];
        return { ...project(la, lo), city: i.city, month: i.month, slug: i.slug };
      }),
    };
  });
}

